      ro: ["Casa gibonului Hoolock de vest, o specie grav amenințată.", "A fost fondat în 1996."],
      en: ["Home to the critically endangered western hoolock gibbon.", "It was established in 1996."],
      es: ["Hogar del gibón de ceja blanca occidental, en peligro crítico.", "Fue fundado en el año 1996."],
      pt: ["Lar do gibão-hoolock-ocidental, criticamente ameaçado.", "Foi fundado em 1996."],
      fr: ["Refuge du gibbon hoolock occidental, espèce gravement menacée.", "A été fondé en 1996."],
